export function parseIntent(text, options){
 const q=text.toLowerCase();
 const tags=[];if(/\b(kid|kids|child|children|family)\b/.test(q))tags.push('family');if(/\b(food|eat|meal|lunch|dinner|hawker|flavors?)\b/.test(q))tags.push('food');if(/\b(culture|art|museum|history|stories)\b/.test(q))tags.push('culture');if(/\b(nature|garden|gardens|green|park|beach)\b/.test(q))tags.push('nature');
 let area=options.area; if(area==='any'){if(/bugis|kampong/.test(q))area='bugis';else if(/chinatown/.test(q))area='chinatown';else if(/marina/.test(q))area='marina';else if(/sentosa/.test(q))area='sentosa';else if(/orchard|civic/.test(q))area='orchard';}
 return {...options,area,tags,indoor:/\b(indoor|indoors|rain|rainy|raining)\b/.test(q),gentle:options.pace==='gentle'||/\b(parents|elderly|relaxed|slow|slower|gentle)\b/.test(q),free:/\bfree\b/.test(q)||Number(options.budget)===0};
}
export function recommend(text,options,category='all'){
 const intent=parseIntent(text,options);const results=places.filter(p=>p.minutes<=Number(intent.hours)*60&&p.cost<=Number(intent.budget)&&(intent.area==='any'||p.area===intent.area)&&(!intent.free||p.cost===0)&&(!intent.indoor||p.tags.includes('indoor'))&&(category==='all'||p.tags.includes(category))).map(p=>{
 const matches=intent.tags.filter(t=>p.tags.includes(t));const score=matches.length*4+(intent.gentle&&p.tags.includes('gentle')?3:0)+(p.cost===0?1:0);let reasons=matches.map(t=>({family:'Family option',food:'Local flavors',culture:'Culture & stories',nature:'A little greenery'})[t]);if(intent.gentle&&p.tags.includes('gentle'))reasons.push('Easy to keep short');if(intent.indoor)reasons.push('Indoor venue');if(p.cost===0)reasons.push('Free entry option');return {...p,score,reason:reasons.slice(0,2).join(' · ')||'Something to explore at your own pace'};
 }).sort((a,b)=>b.score-a.score);
 return {intent,results};
}
export function planSummary(ids){const selected=ids.map(id=>places.find(p=>p.id===id)).filter(Boolean);return {minutes:selected.reduce((n,p)=>n+p.minutes,0)+Math.max(0,selected.length-1)*20,cost:selected.reduce((n,p)=>n+p.cost,0)};}
export function mapsUrl(p,mode='walking'){return `https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(p.name+' Singapore')}&travelmode=${mode}`;}
